//! Parity with the Python counter and basic behaviour of this crate.
//!
//! The vectors come from `assets/tokenizer_parity.json`, generated by
//! `scripts/gen_tokenizer_parity.py`. `backend/tests/test_token_counter.py`
//! asserts the same file, so Rust and Python cannot silently disagree about how
//! many tokens a string is worth.

use std::time::Instant;

use serde::Deserialize;

use super::*;

const FIXTURE_JSON: &str = include_str!("../../../../assets/tokenizer_parity.json");

#[derive(Deserialize)]
struct Fixture {
    vocab: String,
    vectors: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    text: String,
    tokens: i64,
}

fn fixture() -> Fixture {
    match serde_json::from_str(FIXTURE_JSON) {
        Ok(data) => data,
        Err(err) => panic!("parity fixture is invalid JSON: {err}"),
    }
}

fn preview(text: &str) -> String {
    let mut kept: String = text.chars().take(40).collect();
    if kept.len() < text.len() {
        kept.push('…');
    }
    kept
}

#[test]
fn embedded_tokenizer_loads() {
    assert!(is_available(), "embedded tokenizer.json failed to load");
    assert_eq!(tokenizer_name(), VOCAB);
}

#[test]
fn counts_match_the_python_vectors() {
    let data = fixture();
    assert_eq!(data.vocab, VOCAB);
    for vector in data.vectors {
        assert_eq!(
            exact_token_count(&vector.text),
            Some(vector.tokens),
            "count mismatch for {:?}",
            preview(&vector.text)
        );
    }
}

#[test]
fn known_single_cases() {
    assert_eq!(exact_token_count("Hello, world!"), Some(4));
    assert_eq!(exact_token_count(""), Some(0));
    assert_eq!(count_cached(""), 0);
}

#[test]
fn cached_counts_are_identical_to_uncached() {
    let text = "fn main() {\n    println!(\"hi\");\n}\n".repeat(40);
    let direct = token_count_or_approx(&text);
    assert_eq!(count_cached(&text), direct);
    assert_eq!(count_cached(&text), direct);
}

#[test]
fn repeated_counts_are_memoized() {
    // A full context recount is seconds of BPE; the second call must be a cache
    // hit, not another pass over 1.5 MB of text.
    let text = "Line of tool output with some realistic content\n".repeat(22_000);
    let started = Instant::now();
    let first = count_cached(&text);
    let cold = started.elapsed();
    let started = Instant::now();
    assert_eq!(count_cached(&text), first);
    let warm = started.elapsed();
    assert!(first > 50_000, "expected a large fixture, got {first}");
    assert!(
        warm * 20 < cold,
        "cached recount ({warm:?}) is not cheaper than cold ({cold:?})"
    );
}
